param([switch]$ValidateOnly)
$ErrorActionPreference='Stop';$Repo=(Resolve-Path '.').Path
$controlId='v5_hybrid_h2_control_allinonly_same31400_20m_r1_20260713';$treatmentId='v5_hybrid_h2_treatment_showdownk200_same31400_20m_r1_20260713'
$controlDir=Join-Path $Repo "models/alpha_holdem_v5_hybrid/$controlId";$treatmentDir=Join-Path $Repo "models/alpha_holdem_v5_hybrid/$treatmentId"
$source=(Resolve-Path 'models/alpha_holdem_v5_from_zero/v5_zero_l6_exp004_pre001_exp002_multienv_exp003_boundedk_r1_20260709/v5_exp005_cutover_gate31400_checkpoint.pt').Path
